1: /* 详情页 Headline 内编辑表单栅格（与机构基本信息等页面对齐） */
2: .section-form {
3:   display: grid;
4:   grid-template-columns: repeat(3, minmax(0, 1fr));
5:   column-gap: var(--detail-collapse-col-gap, 32px);
6:   row-gap: 0;
7:   align-items: start;
8:   width: 100%;
9:   padding-bottom: 12px;
10:   box-sizing: border-box;
11: }
12: 
13: .section-field {
14:   min-width: 0;
15: }
16: 
17: .section-field--full {
18:   grid-column: 1 / -1;
19: }
20: 
21: /* 文本域表单项默认独占整行（等同 FORM_COL_FULL）；展示态半宽见 DetailTemplate keepSpan */
22: .section-form .section-field:has(.el-textarea),
23: .section-form .section-field:has(.zs-textarea),
24: .scheme-form-grid .section-field:has(.el-textarea),
25: .scheme-form-grid .section-field:has(.zs-textarea) {
26:   grid-column: 1 / -1;
27: }
28: 
29: .section-field--wide {
30:   grid-column: span 2;
31: }
32: 
33: .section-form > .el-row {
34:   grid-column: 1 / -1;
35:   width: 100%;
36: }
37: 
38: .section-form .el-form-item,
39: .section-form .el-input,
40: .section-form .el-select,
41: .section-form .el-cascader,
42: .section-form .el-date-editor,
43: .section-form .amount-input,
44: .section-form .el-textarea,
45: .scheme-form-grid .el-form-item,
46: .scheme-form-grid .el-input,
47: .scheme-form-grid .el-select,
48: .scheme-form-grid .el-textarea {
49:   width: 100%;
50: }
51: 
52: .section-form .el-form-item__label {
53:   white-space: nowrap;
54: }
55: 
56: /* 与输入框同高（38px）垂直居中，避免栅格行内开关贴顶/贴底 */
57: .section-form .el-form-item:has(.el-switch) .el-form-item__content,
58: .scheme-form-grid .el-form-item:has(.el-switch) .el-form-item__content {
59:   display: flex;
60:   align-items: center;
61:   min-height: 38px;
62: }
63: 
64: /*
65:  * 详情 Headline 内表单项：禁止 label-width:auto 整表统一拉宽 + 右标签 margin-left 撑破栅格。
66:  * 统一为列内「标签在上、控件在下」，避免机构变更/价格备案等页标签漂到右侧及反复回流卡死。
67:  */
68: @mixin detail-collapse-form-item-stack {
69:   display: flex;
70:   flex-direction: column;
71:   align-items: flex-start !important;
72:   margin-bottom: 0;
73:   min-width: 0;
74:   width: 100%;
75:   box-sizing: border-box;
76: 
77:   .el-form-item__label {
78:     float: none !important;
79:     display: block !important;
80:     width: 100% !important;
81:     max-width: 100% !important;
82:     text-align: left !important;
83:     justify-content: flex-start !important;
84:     align-self: stretch !important;
85:     line-height: 22px;
86:     padding: 0 0 6px !important;
87:     box-sizing: border-box;
88:   }
89: 
90:   .el-form-item__content {
91:     margin-left: 0 !important;
92:     width: 100% !important;
93:     min-height: 0;
94:     line-height: 1.2;
95:     box-sizing: border-box;
96:     align-self: stretch !important;
97:   }
98: }
99: 
100: /* Headline / 详情折叠区内 zs-search-form：横向标签，避免被 label-top stack 误伤 */
101: @mixin detail-search-form-item-horizontal {
102:   display: flex !important;
103:   flex-direction: row !important;
104:   align-items: center !important;
105:   flex-wrap: nowrap !important;
106:   margin-bottom: 0;
107:   min-width: 0;
108:   width: 100%;
109:   box-sizing: border-box;
110: 
111:   > .el-form-item__label,
112:   > .el-form-item__label-wrap {
113:     float: none !important;
114:     display: inline-block !important;
115:     flex: 0 0 auto;
116:     width: auto !important;
117:     max-width: none !important;
118:     white-space: nowrap !important;
119:     text-align: right !important;
120:     padding: 0 12px 0 0 !important;
121:     line-height: 38px !important;
122:   }
123: 
124:   > .el-form-item__content {
125:     flex: 1 1 auto;
126:     margin-left: 0 !important;
127:     width: auto !important;
128:     min-width: 0;
129:   }
130: }
131: 
132: /* Headline：纵向间距与 label 位置无关（含 label-left 的入网/变更备案 section-form） */
133: .collapse-container > .collapse-content:not(.hide) {
134:   .el-form-item {
135:     margin-bottom: 0 !important;
136:     padding-bottom: 0;
137:   }
138: 
139:   .section-form,
140:   .scheme-form-grid {
141:     padding-bottom: 0;
142:     row-gap: var(--detail-section-form-row-gap);
143:   }
144: 
145:   .section-form .el-form-item,
146:   .scheme-form-grid .el-form-item {
147:     margin-bottom: 0;
148:     box-sizing: border-box;
149:   }
150: 
151:   .el-row:not(.zs-search-form__field-row) > .el-col > .el-form-item,
152:   .el-form > .el-col > .el-form-item,
153:   .zs-form > .el-col > .el-form-item {
154:     margin-bottom: 0;
155:   }
156: }
157: 
158: /* 详情页 / 弹窗：栅格行距仅由 gap 承担（折叠区内另有 padding-bottom: 0） */
159: .detail-container,
160: .detail-from-container,
161: .el-dialog__body {
162:   .el-row:not(.zs-search-form__field-row) .el-form-item,
163:   .section-form .el-form-item,
164:   .scheme-form-grid .el-form-item {
165:     padding-bottom: 0;
166:   }
167: 
168:   .search-form-container .el-form-item,
169:   .zs-search-form__field-row .el-form-item {
170:     padding-bottom: 0;
171:   }
172: }
173: 
174: /* 弹窗内无 el-row 的纵向堆叠：行距由 padding-bottom 承担 */
175: .el-dialog__body {
176:   .el-form > .el-col > .el-form-item,
177:   .zs-form > .el-col > .el-form-item {
178:     padding-bottom: var(--detail-block-gap);
179:   }
180: 
181:   .el-row:not(.zs-search-form__field-row) > .el-col > .el-form-item {
182:     padding-bottom: 0;
183:   }
184: 
185:   /* 弹窗内 section-form / scheme-form-grid 与详情页一致为三列 */
186:   .section-form,
187:   .scheme-form-grid {
188:     grid-template-columns: repeat(3, minmax(0, 1fr));
189:   }
190: 
191:   .section-field--wide {
192:     grid-column: span 2;
193:   }
194: }
195: 
196: .detail-container .el-form--label-top .collapse-content:not(.hide),
197: .detail-from-container .el-form--label-top .collapse-content:not(.hide) {
198:   .section-form .el-form-item,
199:   .el-row:not(.zs-search-form__field-row) > .el-col > .el-form-item,
200:   .el-form > .el-col > .el-form-item,
201:   .zs-form > .el-col > .el-form-item,
202:   .scheme-form-grid .el-form-item {
203:     @include detail-collapse-form-item-stack;
204:   }
205: 
206:   /* 同折叠区内嵌列表筛选条不走 label-top 纵向表单项 */
207:   .search-form-container .el-form-item {
208:     @include detail-search-form-item-horizontal;
209:   }
