246: /* Headline 内 el-row / 存量 zs-form>el-col 使用 flex + column-gap 时，列宽需扣除间距（见 index.scss） */
247: $detail-collapse-el-row: '.collapse-content:not(.hide) .el-row:not(.zs-search-form__field-row):not(.search-form-container .el-row)';
248: $detail-collapse-form-grid: '.collapse-content:not(.hide) .el-form:has(> .el-col), .collapse-content:not(.hide) .zs-form:has(> .el-col)';
249: $detail-collapse-grid: '#{$detail-collapse-el-row}, #{$detail-collapse-form-grid}';
250: 
251: @mixin detail-collapse-col-flex($cols) {
252:   $gap-count: $cols - 1;
253:   flex: 0 0 calc((100% - #{$gap-count} * var(--detail-collapse-col-gap, 32px)) / #{$cols});
254:   max-width: calc((100% - #{$gap-count} * var(--detail-collapse-col-gap, 32px)) / #{$cols});
255:   width: calc((100% - #{$gap-count} * var(--detail-collapse-col-gap, 32px)) / #{$cols}) !important;
256: }
257: 
258: @mixin detail-collapse-col-full-row {
259:   flex: 0 0 100%;
260:   max-width: 100%;
261:   width: 100% !important;
262: }
263: 
264: /* 弹窗内 el-row / 直接挂 el-col 的表单：统一按三列解释 span=8/12/6，span=16 占两列宽 */
265: @mixin detail-dialog-grid-col-sizes {
266:   > .el-col.el-col-24,
267:   > .el-col[class*='el-col-24'],
268:   > .el-col.zs-form-col--full {
269:     @include detail-collapse-col-full-row;
270:   }
271: 
272:   > .el-col.el-col-12,
273:   > .el-col.el-col-sm-12,
274:   > .el-col.el-col-md-12,
275:   > .el-col.el-col-lg-12,
276:   > .el-col.el-col-xl-12,
277:   > .el-col.el-col-8,
278:   > .el-col.el-col-sm-8,
279:   > .el-col.el-col-md-8,
280:   > .el-col.el-col-lg-8,
281:   > .el-col.el-col-xl-8,
282:   > .el-col.el-col-6,
283:   > .el-col.el-col-sm-6,
284:   > .el-col.el-col-md-6,
285:   > .el-col.el-col-lg-6,
286:   > .el-col.el-col-xl-6 {
287:     @include detail-collapse-col-flex(3);
288:   }
289: 
290:   > .el-col.el-col-16,
291:   > .el-col.el-col-sm-16,
292:   > .el-col.el-col-md-16,
293:   > .el-col.el-col-lg-16,
294:   > .el-col.el-col-xl-16,
295:   > .el-col.zs-form-col--wide {
296:     flex: 0 0 calc((100% - var(--detail-collapse-col-gap, 32px)) / 3 * 2);
297:     max-width: calc((100% - var(--detail-collapse-col-gap, 32px)) / 3 * 2);
298:     width: calc((100% - var(--detail-collapse-col-gap, 32px)) / 3 * 2) !important;
299:   }
300: 
301:   > .el-col:has(.el-textarea),
302:   > .el-col:has(.zs-textarea) {
303:     @include detail-collapse-col-full-row;
304:   }
305: }
306: 
307: /* 双列表单弹窗（zs-dialog form-layout="double"）：span=8/12/6/16 统一收敛为半宽，
308:    span=24 与文本域仍整行。双列语义下不存在 2/3 宽度，span=16 由「占三列中的两列」
309:    退化为半宽。作用域前缀 .zs-dialog--form-double 保证存量弹窗零影响。 */
310: @mixin detail-dialog-grid-col-sizes-double {
311:   > .el-col.el-col-24,
312:   > .el-col[class*='el-col-24'],
313:   > .el-col.zs-form-col--full {
314:     @include detail-collapse-col-full-row;
315:   }
316: 
317:   > .el-col.el-col-12,
318:   > .el-col.el-col-sm-12,
319:   > .el-col.el-col-md-12,
320:   > .el-col.el-col-lg-12,
321:   > .el-col.el-col-xl-12,
322:   > .el-col.el-col-8,
323:   > .el-col.el-col-sm-8,
324:   > .el-col.el-col-md-8,
325:   > .el-col.el-col-lg-8,
326:   > .el-col.el-col-xl-8,
327:   > .el-col.el-col-6,
328:   > .el-col.el-col-sm-6,
329:   > .el-col.el-col-md-6,
330:   > .el-col.el-col-lg-6,
331:   > .el-col.el-col-xl-6,
332:   > .el-col.el-col-16,
333:   > .el-col.el-col-sm-16,
334:   > .el-col.el-col-md-16,
335:   > .el-col.el-col-lg-16,
336:   > .el-col.el-col-xl-16,
337:   > .el-col.zs-form-col--wide {
338:     @include detail-collapse-col-flex(2);
339:   }
340: 
341:   /* 置于列宽规则之后，避免 el-col-8/12/16 覆盖整行 */
342:   > .el-col:has(.el-textarea),
343:   > .el-col:has(.zs-textarea) {
344:     @include detail-collapse-col-full-row;
345:   }
346: }
347: 
348: /* 单列表单弹窗（zs-dialog form-layout="single"）：所有字段整行，禁止三列语义 */
349: @mixin detail-dialog-grid-col-sizes-single {
350:   > .el-col {
351:     @include detail-collapse-col-full-row;
352:   }
353: }
354: 
355: /* 无 el-row 包裹时，表单本身作为 flex 栅格容器（与 index.scss 中 el-row 规则对齐） */
356: #{$detail-collapse-form-grid} {
