276: .detail-from-container {
277:   display: flex;
278:   flex-direction: column;
279:   flex: 1;
280:   min-height: 0;
281:   width: 100%;
282:   margin: 0 !important;
283:   background-color: transparent;
284:   gap: var(--detail-section-gap) !important;
285:   overflow-x: hidden;
286:   overflow-y: auto;
287:   /* 滚动条槽位恒定：内容高度贴近容器高度时，滚动条出现/消失不再引起 ±15px 宽度摆动，
288:      避免 label-width:auto 重新量测 → 重排 → 滚动条消失 → 再量测 的抖动闭环 */
289:   scrollbar-gutter: stable;
290:   box-sizing: border-box;
